          "phone": "{{ trigger_id = 'wa' ? trigger.from : (trigger.phone ? $replace($string(trigger.phone), /[^0-9]/, '') : null) }}",
          "message": "{{ trigger_id = 'wa' ? trigger.text : trigger.message }}"
